"""Run the locked P7 cis-MR plan using only local served tables."""
import json
import math
from collections import Counter, defaultdict
from decimal import Decimal
from pathlib import Path

import numpy as np

from harmonise import (Aliases, Audit, deduplicate, finite, join, keyname,
                       load_associations, protein_filter, rank, row_summary, sha256)
from ld import analyse_ld
from statistics_core import coloc_keys, wald


OUT = Path('outputs')


def jsonable(x):
    if isinstance(x, dict):
        return {str(k): jsonable(v) for k, v in x.items()}
    if isinstance(x, (list, tuple)):
        return [jsonable(v) for v in x]
    if isinstance(x, np.integer):
        return int(x)
    if isinstance(x, np.floating):
        x = float(x)
    if isinstance(x, float) and not math.isfinite(x):
        return None
    return x


def write(name, value):
    path = OUT/name
    path.write_text(json.dumps(jsonable(value), indent=2, allow_nan=False)+'\n')
    if path.stat().st_size > 50000000:
        raise ValueError(f'Output file exceeds limit: {path}')


def outcome_category(k, raw_outcomes):
    if any(k not in y for y in raw_outcomes.values()):
        raise ValueError('Mandatory outcome association not identifiable for '+keyname(k))
    n = sum(y[k]['p_decimal'] < Decimal('.05') for y in raw_outcomes.values())
    return {0: 'associated-in-neither', 1: 'associated-in-one', 2: 'associated-in-both'}[n]


def identify_reference(raw, aliases, ref, audit=None):
    """Anchor the instrument to its protein row before joining outcome tables.

    Exact served tokens take precedence over a registry expansion. An outcome
    list cell or an alias group can cover more than one allele-specific record;
    that does not change which protein association defines the instrument.
    No association values or significance thresholds enter this resolution.
    """
    equivalent = aliases.equivalent(ref)
    exact = {ds: {r['key'] for r in rows if ref in r['tokens']}
             for ds, rows in raw.items()}
    expanded = {ds: {r['key'] for r in rows if equivalent.intersection(r['tokens'])}
                for ds, rows in raw.items()}
    protein_keys = {r['key'] for r in raw['C']}
    protein_exact = exact['C']
    if protein_exact:
        candidates = protein_exact
        method = 'exact reference token in protein table'
    else:
        other_exact = set().union(*(ks for ds, ks in exact.items() if ds != 'C'))
        if other_exact:
            candidates = other_exact & protein_keys
            method = 'exact reference token in outcome tables, joined to protein by coordinate/alleles'
        elif expanded['C']:
            candidates = expanded['C']
            method = 'decoded reference alias in protein table'
        else:
            candidates = set().union(*expanded.values()) & protein_keys
            method = 'decoded reference alias joined to protein by coordinate/alleles'
    details = {'reference_token': ref, 'method': method,
               'exact_keys_by_dataset': {ds: [keyname(k) for k in sorted(ks)] for ds, ks in exact.items()},
               'alias_keys_by_dataset': {ds: [keyname(k) for k in sorted(ks)] for ds, ks in expanded.items()}}
    if len(candidates) != 1:
        if audit is not None:
            audit.event('reference', 'reference protein association not uniquely identifiable', **details)
        raise ValueError(f'Reference {ref} resolves to {len(candidates)} protein coordinate/allele keys '
                         f'using {method}; no proxy or arbitrary allele was selected')
    chosen = next(iter(candidates))
    if audit is not None:
        audit.event('reference', 'reference protein association resolved', chosen, **details)
        extras = set().union(*expanded.values()) - {chosen}
        if extras:
            audit.event('reference', 'reference token or alias covers multiple keys; protein key anchors join',
                        chosen, other_keys=[keyname(k) for k in sorted(extras)])
    return chosen


def precision_summary(x, y, keys):
    keys = sorted(keys)
    se = np.array([y[k]['standard_error'] for k in keys])
    f = np.array([y[k]['effect_allele_frequency'] for k in keys])
    info = 1/(2*f*(1-f)*se*se)
    ok = np.isfinite(info) & (f > 0) & (f < 1)
    return {'n': len(keys), 'standard_error_quantiles': np.quantile(se, [0, .25, .5, .75, 1]).tolist(),
            'frequency_scaled_precision_quantiles': np.quantile(info[ok], [0, .25, .5, .75, 1]).tolist() if ok.any() else [],
            'note': 'Frequency-scaled precision is a diagnostic proxy, not a known per-variant sample size.'}


def reference_availability(ref, ref_token, raw, unique, protein, outcomes, audit):
    """Explain a required-input failure without relaxing a scientific check."""
    available = {'C': protein, 'B': outcomes['c1'], 'D': outcomes['c2']}
    checks = {}
    for ds in ['C', 'B', 'D']:
        matching = [r for r in raw[ds] if r['key'] == ref]
        if ref in available[ds]:
            status = 'usable'
        elif not matching:
            status = 'required coordinate/allele key absent'
        elif not any(r['valid'] for r in matching):
            status = 'all records at required key have invalid association fields'
        elif ref not in unique[ds]:
            status = 'conflicting duplicate associations excluded by locked rule'
        elif ds != 'C' and ref not in protein:
            status = 'protein reference excluded before outcome join'
        else:
            status = 'excluded by locked allele/frequency harmonisation rule'
        checks[ds] = {
            'status': status,
            'raw_records_at_required_key': len(matching),
            'valid_raw_records_at_required_key': sum(bool(r['valid']) for r in matching),
            'retained_after_duplicate_qc': ref in unique[ds],
            'usable_after_harmonisation': ref in available[ds],
            'exact_reference_token_keys': sorted({keyname(r['key']) for r in raw[ds] if ref_token in r['tokens']}),
            'audit_events_at_required_key': [e for e in audit.events if e['dataset'] == ds and e['key'] == keyname(ref)]
        }
    return {'reference_token': ref_token, 'required_key': keyname(ref),
            'ready': all(c['usable_after_harmonisation'] for c in checks.values()),
            'datasets': checks,
            'constraint': 'Use the same coordinate/allele instrument in C, B and D. No proxy, identifier-only mismatch, imputed effect or dummy estimate is permitted.'}


def reference_failure_message(check):
    failed = '; '.join(ds+': '+c['status'] for ds, c in check['datasets'].items()
                       if not c['usable_after_harmonisation'])
    key_evidence = {'required_key': check['required_key'],
                    'exact_reference_token_keys': {
                        ds: c['exact_reference_token_keys'] for ds, c in check['datasets'].items()}}
    return ('Mandatory reference variant is not valid in all MR datasets after harmonisation. '
            + failed + '. Join-key evidence: ' + json.dumps(key_evidence, sort_keys=True)
            + '. See outputs/reference-check.json and outputs/qc.json. '
            'The locked plan forbids substituting an instrument or inventing a primary estimate.')


def verify_report(report, primary, plan):
    assert set(primary['claims']) == set(plan['paper_set'])
    assert report['direction'] in ['higher-decreases-risk', 'higher-increases-risk', 'no-detectable-effect']
    assert report['replication'] in ['concordant-not-weaker', 'concordant-weaker', 'not-significant', 'opposite-direction']
    categories = ['associated-in-both', 'associated-in-one', 'associated-in-neither']
    assert report['locus']['reference_variant_outcome'] in categories
    assert report['locus']['strongest_variant_outcome'] in categories
    assert report['locus']['architecture'] in ['single-signal', 'multiple-signals']
    assert isinstance(report['locus']['strongest_variant'], str)
    assert isinstance(report['locus']['n_significant_variants'], int)
    for cohort in ['c1', 'c2']:
        mr = report['mr'][cohort]
        assert all(isinstance(mr[k], float) and math.isfinite(mr[k]) for k in ['wald_lnor', 'wald_ci_lower', 'wald_ci_upper'])
        assert mr['wald_ci_lower'] <= mr['wald_lnor'] <= mr['wald_ci_upper']
        co = report['coloc'][cohort]
        assert 0 <= co['pp_h4'] <= 1 and math.isfinite(co['pp_h4'])
        assert co['verdict'] in ['shared-variant', 'distinct-variants', 'inconclusive']


def main():
    OUT.mkdir(exist_ok=True)
    Path('tmp').mkdir(exist_ok=True)
    plan = json.loads(Path('plan.json').read_text())
    metadata = json.loads(Path('code/public-metadata.json').read_text())
    assert metadata == plan['sharedKnobs']['public_metadata']
    audit = Audit()
    paths = {k: Path(v['path']) for k, v in metadata['sources'].items()}
    for path in paths.values():
        assert path.parent == Path('data')
    provenance = {'plan_sha256': sha256('plan.json'),
                  'input_sha256': {str(p): sha256(p) for p in list(paths.values())+[Path('data/snp-aliases.tsv')]},
                  'code_sha256': {str(p): sha256(p) for p in sorted(Path('code').glob('*.py'))},
                  'source_metadata': metadata}
    aliases = Aliases('data/snp-aliases.tsv', audit)
    raw = {k: load_associations(paths[k], k, audit) for k in ['B', 'C', 'D']}
    unique = {k: deduplicate(rows, k, audit) for k, rows in raw.items()}
    # Cross-table alias reuse is checked against coordinate/allele identity, not participant identity.
    alias_keys = defaultdict(set)
    for rows in raw.values():
        for r in rows:
            for t in r['tokens']:
                alias_keys[aliases.root(t)].add(r['key'])
    for root, ks in alias_keys.items():
        if len(ks) > 1:
            audit.event('registry', 'alias group maps to multiple variant keys', token=root,
                        keys=[keyname(k) for k in sorted(ks)])
    x = protein_filter(unique['C'], audit)
    y = {'c1': join(x, unique['B'], 'B', audit), 'c2': join(x, unique['D'], 'D', audit)}
    try:
        ref = identify_reference(raw, aliases, metadata['reference_variant'], audit)
    except ValueError:
        write('qc.json', {'events': audit.events, 'stats': audit.stats})
        raise
    reference_check = reference_availability(ref, metadata['reference_variant'], raw, unique, x, y, audit)
    write('reference-check.json', reference_check)
    if not reference_check['ready']:
        write('qc.json', {'events': audit.events, 'stats': audit.stats})
        raise ValueError(reference_failure_message(reference_check))
    mr = {c: wald(x[ref]['beta'], yy[ref]['beta'], yy[ref]['standard_error']) for c, yy in y.items()}
    primary = {'claims': {f'p7-outcome-a-{c}-mr': {k: v for k, v in m.items() if k != 'ci'} for c, m in mr.items()}}
    # These normal first-order intervals are not registered decision intervals.
    write('primary.json', primary)
    diagnostics = {'claims': {}, 'reference': {'key': keyname(ref), 'protein': row_summary(x[ref]),
                   'outcomes': {c: row_summary(yy[ref]) for c, yy in y.items()},
                   'protein_F': (x[ref]['beta']/x[ref]['standard_error'])**2}}
    for c, m in mr.items():
        cid = f'p7-outcome-a-{c}-mr'
        mei = next(q['mei'] for q in plan['claims'] if q['id'] == cid)
        diagnostics['claims'][cid] = {'estimate': m['estimate'], 'se': m['se'], 'p': m['p'],
            'wald_first_order_95_ci': m['ci'], 'method': 'Normal Wald ratio; first-order SE = outcome SE / abs(protein beta)',
            'status': 'exploratory; cross-table IV estimator is outside registered designs',
            'n_units': 1, 'unit': 'prespecified variant instrument; underlying GWAS participants are not available',
            'mei': mei, 'point_magnitude_exceeds_mei': abs(m['estimate']) >= mei,
            'ci_entirely_above_mei': m['ci'][0] > mei, 'ci_entirely_below_negative_mei': m['ci'][1] < -mei,
            'registered_decision_interval_computed': False}
    write('diagnostics.json', diagnostics)
    print('Computed both reference-variant Wald estimates and first-order intervals.', flush=True)
    raw_valid = [r for r in raw['C'] if r['p_decimal'].is_finite() and 0 <= r['p_decimal'] <= 1]
    significant_count = sum(r['p_decimal'] < Decimal('5e-8') for r in raw_valid)
    strongest = min(raw_valid, key=rank)
    strongest_key = strongest['key']
    strongest_tokens = strongest['tokens']
    if not strongest_tokens:
        strongest_tokens = sorted({t for ds in unique.values() if strongest_key in ds for t in ds[strongest_key]['tokens']})
        roots = {aliases.root(t) for t in strongest_tokens}
        if len(roots) != 1:
            raise ValueError('Strongest variant lacks a uniquely recoverable served identifier')
    strongest_token = aliases.preferred(strongest_tokens)
    if not strongest_token:
        raise ValueError('Strongest variant token unavailable')
    raw_outcome = {'c1': unique['B'], 'c2': unique['D']}
    reference_cat = outcome_category(ref, raw_outcome)
    strongest_cat = outcome_category(strongest_key, raw_outcome)
    ties = sum(r['p_decimal'] == strongest['p_decimal'] for r in raw_valid)
    diagnostics['strongest_variant'] = {'protein': row_summary(strongest), 'tied_minimum_rows': ties,
        'reported_token': strongest_token,
        'outcomes': {c: row_summary(yy[strongest_key]) for c, yy in raw_outcome.items()}}
    window = {k for k in x if k[0] == ref[0] and abs(k[1]-ref[1]) <= 50000}
    coloc = {}
    pairkeys = {c: window & yy.keys() for c, yy in y.items()}
    for c, yy in y.items():
        coloc[c] = coloc_keys(pairkeys[c], x, yy)
        if 'pp_h4' not in coloc[c]:
            raise ValueError(c+': mandatory colocalisation not estimable')
    common = pairkeys['c1'] & pairkeys['c2']
    coloc_sensitivity = {'common_C_B_D_intersection': {c: coloc_keys(common, x, yy) for c, yy in y.items()},
                        'frequency_difference_le_010': {}}
    for c, yy in y.items():
        good = {k for k in pairkeys[c] if finite(x[k]['effect_allele_frequency'])
                and finite(yy[k]['effect_allele_frequency'])
                and abs(x[k]['effect_allele_frequency']-yy[k]['effect_allele_frequency']) <= .10}
        coloc_sensitivity['frequency_difference_le_010'][c] = coloc_keys(good, x, yy)
    diagnostics['coloc_primary'] = coloc
    diagnostics['coloc_sensitivity'] = coloc_sensitivity
    diagnostics['coloc_variant_keys'] = {c: [keyname(k) for k in sorted(ks)] for c, ks in pairkeys.items()}
    diagnostics['precision'] = {c: precision_summary(x, yy, pairkeys[c]) for c, yy in y.items()}
    print('Computed pairwise and sensitivity colocalisation; independent numeric checks passed.', flush=True)
    ld, ld_keys = analyse_ld(paths['A'], x, audit)
    diagnostics['conditional_signals'] = ld
    leads = ld['primary']['leads']
    if not leads:
        write('diagnostics.json', diagnostics)
        write('qc.json', {'events': audit.events, 'stats': audit.stats})
        raise ValueError('No genome-wide significant LD-eligible protein signal: architecture cannot be classified')
    architecture = 'multiple-signals' if len(leads) > 1 else 'single-signal'
    a, b = mr['c1'], mr['c2']
    direction = 'higher-decreases-risk' if a['ci'][1] < 0 else (
        'higher-increases-risk' if a['ci'][0] > 0 else 'no-detectable-effect')
    if a['estimate']*b['estimate'] < 0:
        replication = 'opposite-direction'
    elif b['ci'][0] <= 0 <= b['ci'][1]:
        replication = 'not-significant'
    elif a['estimate'] == 0 and b['estimate'] != 0:
        replication = 'opposite-direction'
    else:
        replication = 'concordant-not-weaker' if abs(b['estimate']) >= abs(a['estimate']) else 'concordant-weaker'
    for ds, source in metadata['sources'].items():
        observed = audit.stats[ds]['raw_rows']
        if observed != source['rows']:
            audit.problems.append(f'{ds}: observed {observed} rows; public metadata specifies {source["rows"]}')
    # Missing matches and the required palindrome exclusion are analysis coverage, not invented data defects.
    problem_phrases = ['invalid', 'conflicting', 'differs', 'multiple', 'heterozygosity', 'near-identical', 'missingness']
    event_summary = audit.summarize()
    for e in event_summary:
        if any(s in e['reason'] for s in problem_phrases):
            audit.problems.append(f'{e["dataset"]}: {e["count"]} {e["reason"]}')
    for ds in ['B', 'C', 'D']:
        missing = audit.stats[ds]['missing_by_column']
        if missing['variant']:
            audit.problems.append(f'{ds}: {missing["variant"]} missing variant identifiers; coordinate/allele joins used')
    caveats = [
        'The direction label follows the prespecified C1 interval; it is not a proof that P7 causes Outcome A.',
        'MR requires instrument relevance and absence of horizontal pleiotropy or other pathways violating the exclusion restriction.',
        'First-order MR intervals ignore uncertainty in the protein effect; instrument F and effects are in diagnostics.json.',
        'GWAS participant overlap cannot be verified from summary data; both ratios share the protein estimate.',
        'LD is estimated in a finite European reference sample; conditional z tests approximate regression and can be unstable in strong LD.',
        'Single-causal marginal colocalisation can be misleading with multiple signals and does not demonstrate protein mediation.',
        'Uneven variant precision, winner\u2019s curse and untested protein-assay binding effects may affect interpretation; findings concern this cis locus and ancestry.',
        'Statistical significance and the prespecified log(1.10) practical magnitude threshold are reported separately; no equivalence claim is made.'
    ]
    if ld['significant_protein_keys_without_ld']:
        caveats.append(f'{len(ld["significant_protein_keys_without_ld"])} significant harmonised protein variants lack usable LD; architecture applies to analyzable variants.')
    joint_lost = [r['key'] for r in leads if r.get('joint_conditional_p', 1) >= 5e-8]
    if joint_lost:
        caveats.append(f'{len(joint_lost)} sequentially selected signals do not retain p<5e-8 in the final joint retest; inspect conditional diagnostics.')
    near_window = sum(abs(int(r['key'].split(':')[1])-ref[1]) <= 50000 for r in leads)
    if near_window > 1:
        caveats.append('Multiple selected protein signals are inside the colocalisation window, violating the primary single-causal model.')
    if replication == 'opposite-direction':
        caveats.append('C2 has the opposite MR point-estimate direction to C1; the primary directional finding is not replicated.')
    if any(q['verdict'] == 'distinct-variants' for q in coloc.values()):
        caveats.append('At least one cohort supports distinct causal variants, weakening interpretation of the Wald ratio as a P7-mediated effect.')
    exclusion_counts = Counter(e['reason'] for e in audit.events if 'palindrom' in e['reason'] or 'allele' in e['reason'])
    method = (
        f'Marginal single-causal-variant Wakefield ABF colocalisation within inclusive +/-50 kb of V21461189 '
        f'({ref[0]}:{ref[1]}), with separate harmonised C-B ({len(pairkeys["c1"])} variants) and '
        f'C-D ({len(pairkeys["c2"])} variants) intersections. Unique coordinate/allele keys, protein effect-allele alignment, '
        f'protein MAF>0.42 palindromes removed and remaining ambiguous palindromes excluded; '
        f'allele/palindrome exclusion events: {dict(sorted(exclusion_counts.items()))}. '
        'Source beta and variant-specific SE were used, retaining imprecise C1 variants. '
        'Priors p1=p2=1e-4 and p12=1e-5; normal effect prior SDs 0.15 for standardised protein and 0.2 for log odds. '
        'H0-H4 weights were normalised in log space and independently checked. Primary results are unconditioned; '
        'common-intersection and frequency-concordance sensitivities are in diagnostics.json.'
    )
    report = {
        'mr': {c: {'wald_lnor': m['estimate'], 'wald_ci_lower': m['ci'][0], 'wald_ci_upper': m['ci'][1]} for c, m in mr.items()},
        'direction': direction, 'replication': replication,
        'locus': {'reference_variant_outcome': reference_cat, 'n_significant_variants': significant_count,
                  'strongest_variant': strongest_token, 'strongest_variant_outcome': strongest_cat, 'architecture': architecture},
        'coloc': {**{c: {'pp_h4': q['pp_h4'], 'verdict': q['verdict']} for c, q in coloc.items()}, 'method': method},
        'integrity': {'duplicated_or_overlapping_units': sorted(set(audit.duplicates)),
                      'other_data_quality_problems': sorted(set(audit.problems)),
                      'units_of_analysis': f'Unique chromosome-position-allele variants for joins/colocalisation; one V21461189 instrument per cohort; {audit.stats["A"]["retained_individuals"]} retained reference genotype profiles for LD; original protein rows for the significant-row count.'},
        'caveats': caveats}
    verify_report(report, primary, plan)
    diagnostics['verification'] = {'report_fields_validated': True, 'independent_abf_agreement': True,
        'allele_flip_mr_invariance': True, 'ld_symmetry_and_unit_diagonal': True,
        'plan_sha256': provenance['plan_sha256'], 'primary_ci_omission': 'No registered interval computed; normal Wald intervals are explicitly named diagnostic quantities.'}
    write('task-results.json', report)
    # The execution contract requires all final writes under outputs/.
    write('report.json', report)
    write('diagnostics.json', diagnostics)
    write('qc.json', {'stats': audit.stats, 'event_summary': event_summary, 'events': audit.events})
    write('provenance.json', provenance)
    assert json.loads((OUT/'report.json').read_text()) == json.loads((OUT/'task-results.json').read_text())
    print('Wrote primary.json, task-results.json, report.json, diagnostics.json, qc.json and provenance.json under outputs/.', flush=True)


if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        OUT.mkdir(exist_ok=True)
        write('analysis-error.json', {'error_type': type(error).__name__, 'message': str(error),
              'policy': 'No proxy instrument, dummy estimate, or invented mandatory answer was substituted.'})
        raise

"""Deterministic coordinate/allele joins; no identifier-order inference."""
import hashlib
import json
import math
from collections import Counter, defaultdict
from decimal import Decimal, InvalidOperation
from pathlib import Path

import numpy as np
import pandas as pd
from scipy.stats import norm

COMP = str.maketrans('ACGT', 'TGCA')
NUMERIC = ['beta', 'standard_error', 'effect_allele_frequency', 'p_value']


def tokens(cell):
    return sorted(set(x.strip() for x in str(cell).split(',') if x.strip() not in ('', 'NA', 'nan')))


def palindrome(r):
    return frozenset((r['effect_allele'], r['other_allele'])) in (frozenset('AT'), frozenset('CG'))


def key(r):
    a, b = r['effect_allele'], r['other_allele']
    pair = tuple(sorted((a, b)))
    if len(a) == len(b) == 1 and a in 'ACGT' and b in 'ACGT':
        pair = min(pair, tuple(sorted((a.translate(COMP), b.translate(COMP)))))
    return (r['chromosome'], int(r['position']), *pair)


def keyname(k):
    return ':'.join(map(str, k))


def finite(x):
    return math.isfinite(float(x))


def orientations(target, source):
    a, b = target['effect_allele'], target['other_allele']
    c, d = source['effect_allele'], source['other_allele']
    possibilities = [(c, d)]
    if len(c) == len(d) == 1 and c in 'ACGT' and d in 'ACGT':
        possibilities.append((c.translate(COMP), d.translate(COMP)))
    result = set()
    for u, v in possibilities:
        if (a, b) == (u, v):
            result.add(1)
        if (a, b) == (v, u):
            result.add(-1)
    return result


def orient(target, source):
    signs = orientations(target, source)
    if not signs:
        return None, 'incompatible alleles'
    if palindrome(target):
        f, g = target['effect_allele_frequency'], source['effect_allele_frequency']
        if not (finite(f) and finite(g)):
            return None, 'palindrome missing frequency'
        if min(f, 1-f) > 0.42:
            return None, 'protein palindrome MAF > 0.42'
        options = sorted((abs(f-(g if s == 1 else 1-g)), s) for s in signs)
        if options[0][0] > 0.10 or (len(options) > 1 and options[1][0]-options[0][0] < 0.05):
            return None, 'ambiguous palindrome frequency'
        return options[0][1], None
    if len(signs) != 1:
        return None, 'ambiguous orientation'
    return next(iter(signs)), None


def aligned(r, target, sign):
    q = dict(r)
    q['effect_allele'] = target['effect_allele']
    q['other_allele'] = target['other_allele']
    q['beta'] *= sign
    if sign == -1:
        q['effect_allele_frequency'] = 1-q['effect_allele_frequency']
    q['alignment_sign'] = sign
    return q


class Audit:
    def __init__(self):
        self.events = []
        self.duplicates = []
        self.problems = []
        self.stats = {}

    def event(self, dataset, reason, k=None, **details):
        self.events.append({'dataset': dataset, 'reason': reason,
                            'key': keyname(k) if k is not None else None, **details})

    def summarize(self):
        counts = Counter((x['dataset'], x['reason']) for x in self.events)
        return [{'dataset': a, 'reason': b, 'count': n} for (a, b), n in sorted(counts.items())]


class Aliases:
    def __init__(self, path, audit):
        self.groups = defaultdict(set)
        self.canonical = {}
        self.parent = {}
        df = pd.read_csv(path, sep='\t', dtype=str, keep_default_na=False)
        canonical_pairs = []
        for r in df.to_dict('records'):
            vals = []
            for col in ('original', 'canonical', 'target'):
                val = r.get(col, '')
                if not val:
                    continue
                try:
                    decoded = json.loads(val)
                except (ValueError, TypeError):
                    decoded = val  # Served development registry may use token encoding.
                if isinstance(decoded, str):
                    vals.append((col, decoded))
            if not vals:
                continue
            for _, v in vals:
                self.parent.setdefault(v, v)
            first = vals[0][1]
            for _, v in vals[1:]:
                self.parent[self.root(v)] = self.root(first)
            dd = dict(vals)
            if 'canonical' in dd:
                canonical_pairs.extend((v, dd['canonical']) for _, v in vals)
        for v in self.parent:
            self.groups[self.root(v)].add(v)
        for v, c in canonical_pairs:
            if v in self.canonical and self.canonical[v] != c:
                audit.event('registry', 'conflicting canonical mapping', token=v)
            self.canonical[v] = c

    def root(self, x):
        if x not in self.parent:
            return x
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def equivalent(self, x):
        return self.groups.get(self.root(x), {x})

    def preferred(self, values):
        values = set(values)
        preferred = {self.canonical[v] for v in values if v in self.canonical} & values
        return min(preferred or values) if values else None


def load_associations(path, dataset, audit):
    df = pd.read_csv(path, sep='\t', dtype=str, keep_default_na=False)
    needed = ['chromosome', 'position', 'effect_allele', 'other_allele', 'variant']+NUMERIC
    if not set(needed).issubset(df.columns):
        raise ValueError(f'{dataset}: required columns absent')
    records = []
    for idx, src in enumerate(df.to_dict('records')):
        r = dict(src)
        r['source_row'] = idx+2
        r['tokens'] = tokens(src['variant'])
        try:
            r['position'] = int(src['position'])
            r['p_decimal'] = Decimal(src['p_value'])
        except (ValueError, InvalidOperation):
            audit.event(dataset, 'invalid position or p-value', row=idx+2)
            continue
        for col in NUMERIC:
            try:
                r[col] = float(src[col])
            except ValueError:
                r[col] = float('nan')
        r['effect_allele'] = r['effect_allele'].upper()
        r['other_allele'] = r['other_allele'].upper()
        r['key'] = key(r)
        r['valid'] = (finite(r['beta']) and finite(r['standard_error']) and r['standard_error'] > 0
                      and r['p_decimal'].is_finite() and 0 <= r['p_decimal'] <= 1
                      and r['effect_allele'] not in ('', 'NA') and r['other_allele'] not in ('', 'NA')
                      and r['effect_allele'] != r['other_allele'])
        f = r['effect_allele_frequency']
        if finite(f) and not 0 <= f <= 1:
            r['valid'] = False
        if not r['valid']:
            audit.event(dataset, 'invalid association', r['key'], row=idx+2)
        elif r['p_decimal'] > 0:
            lp = float(r['p_decimal'].ln())
            expected = float(math.log(2)+norm.logsf(abs(r['beta']/r['standard_error'])))
            if abs(lp-expected) > math.log(10):
                audit.event(dataset, 'p-value differs from beta/SE normal p by >10-fold', r['key'])
        records.append(r)
    audit.stats[dataset] = {'raw_rows': len(df), 'parsed_rows': len(records),
                            'missing_by_column': {c: int(df[c].isin(['', 'NA']).sum()) for c in needed}}
    return records


def deduplicate(records, dataset, audit):
    groups = defaultdict(list)
    token_keys = defaultdict(set)
    for r in records:
        if r['valid']:
            groups[r['key']].append(r)
        for t in r['tokens']:
            token_keys[t].add(r['key'])
    for t, ks in token_keys.items():
        if len(ks) > 1:
            audit.event(dataset, 'variant token maps to multiple allele keys', token=t)
    result = {}
    for k, rows in sorted(groups.items()):
        # Sorting gives deterministic representative selection independent of source row order.
        rows.sort(key=lambda r: (r['effect_allele'], r['other_allele'], tuple(r['tokens'])))
        base = dict(rows[0])
        equivalent = True
        for r in rows[1:]:
            signs = orientations(base, r)
            ok = False
            for s in signs:
                q = aligned(r, base, s)
                same_numeric = all((math.isnan(base[c]) and math.isnan(q[c])) or
                                   math.isclose(base[c], q[c], rel_tol=1e-12, abs_tol=1e-14)
                                   for c in NUMERIC[:-1])
                if same_numeric and base['p_decimal'] == q['p_decimal']:
                    ok = True
            equivalent &= ok
        if len(rows) > 1:
            label = dataset+':'+keyname(k)
            audit.duplicates.append(label)
            audit.event(dataset, 'identical duplicate association collapsed' if equivalent else
                        'conflicting duplicate association excluded', k, rows=len(rows))
        if equivalent:
            base['tokens'] = sorted({t for r in rows for t in r['tokens']})
            result[k] = base
    return result


def protein_filter(records, audit):
    result = {}
    for k, r in records.items():
        if palindrome(r):
            f = r['effect_allele_frequency']
            if not finite(f) or min(f, 1-f) > 0.42:
                audit.event('C', 'protein palindrome excluded: missing frequency or MAF > 0.42', k)
                continue
        result[k] = r
    return result


def join(protein, outcome, dataset, audit):
    result = {}
    for k, x in sorted(protein.items()):
        if k not in outcome:
            audit.event(dataset, 'no matching outcome key', k)
            continue
        sign, reason = orient(x, outcome[k])
        if sign is None:
            audit.event(dataset, reason, k)
            continue
        y = aligned(outcome[k], x, sign)
        result[k] = y
        f, g = x['effect_allele_frequency'], y['effect_allele_frequency']
        if finite(f) and finite(g) and abs(f-g) > 0.10:
            audit.event(dataset, 'aligned frequency differs from protein by >0.10', k)
    audit.stats[dataset]['protein_matched'] = len(result)
    return result


def rank(r):
    p = r['p_decimal']
    ztie = -abs(r['beta']/r['standard_error']) if p == 0 and r['valid'] else 0
    return (p, ztie, r['key'], tuple(r['tokens']))


def row_summary(r):
    return {k: r[k] for k in ['chromosome', 'position', 'effect_allele', 'other_allele',
                              'beta', 'standard_error', 'effect_allele_frequency', 'tokens']} | {
        'p_value': str(r['p_decimal'])}


def sha256(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()
